import os
import rasterio
import numpy as np

# Path to your .data folder generated by SNAP
data_dir = "Timure_S1_TimeSeries_Stack.data"

# Find all .img files in the directory (sorted to maintain band/time order)
img_files = sorted([f for f in os.listdir(data_dir) if f.endswith('.img')])

print(f"Found {len(img_files)} band files in the stack.")

stack_bands = []
profile = None

for i, img_file in enumerate(img_files):
    img_path = os.path.join(data_dir, img_file)
    with rasterio.open(img_path) as src:
        # Read the single band data into a 2D numpy array
        band_data = src.read(1).astype(np.float32)
        stack_bands.append(band_data)
        
        # Capture profile metadata from the first valid band
        if profile is None:
            profile = src.profile

# Convert list of 2D arrays into a single 3D NumPy array: shape (bands, height, width)
stack_array = np.array(stack_bands)

print(f"Successfully loaded stack!")
print(f"Stack Array Shape (Bands, Height, Width): {stack_array.shape}")
print(f"Coordinate Reference System: {profile['crs']}")

# Example: Check min/max values for the first band (2026-05-05 VV)
print(f"Band 1 ({img_files[0]}) Min: {np.nanmin(stack_array[0])}, Max: {np.nanmax(stack_array[0])}")